const fs = require('fs');
const zlib = require('zlib');
const path = require('path');

const source = path.join(__dirname, 'input.txt');
const destination = path.join(__dirname, 'input.txt.gz');

fs.writeFileSync(source, 'Compressing file stream payload with Gzip transform');

fs.createReadStream(source)
    .pipe(zlib.createGzip())
    .pipe(fs.createWriteStream(destination))
    .on('finish', () => console.log('File compressed successfully!'));

const http = require('http');

const server = http.createServer((req, res) => {
    if (req.method === 'POST' && req.url === '/api/data') {
        let body = '';
        req.on('data', chunk => body += chunk.toString());
        req.on('end', () => {
            try {
                const parsed = JSON.parse(body);
                res.writeHead(200, { 'Content-Type': 'application/json' });
                res.end(JSON.stringify({ received: parsed }));
            } catch (err) {
                res.writeHead(400);
                res.end(JSON.stringify({ error: 'Invalid JSON' }));
            }
        });
    }
});

server.listen(5001);

