const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
    console.log('Main thread initiating CPU worker...');
    const worker = new Worker(__filename, { workerData: { count: 100000 } });
    worker.on('message', result => console.log('Result from Worker:', result));
} else {
    // Executing inside Worker Thread
    let sum = 0;
    for (let i = 0; i < workerData.count; i++) sum += i;
    parentPort.postMessage(sum);
}

