const shutdown = (signal) => {
    console.log(`Received ${signal}. Closing HTTP server gracefully...`);
    server.close(() => {
        console.log('HTTP server closed. Exiting process.');
        process.exit(0);
    });
};

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

