class MiddlewareRunner {
    constructor() {
        this.middlewares = [];
    }

    use(fn) {
        this.middlewares.push(fn);
    }

    run(req, res) {
        let index = 0;
        const next = () => {
            if (index < this.middlewares.length) {
                const middleware = this.middlewares[index++];
                middleware(req, res, next);
            }
        };
        next();
    }
}

const runner = new MiddlewareRunner();
runner.use((req, res, next) => { req.user = 'Alex'; next(); });
runner.use((req, res, next) => { console.log('Auth Middleware:', req.user); next(); });
runner.run({}, {});

const http = require('http');
const fs = require('fs').promises;
const path = require('path');

const DB_PATH = path.join(__dirname, 'posts_db.json');

const readDb = async () => {
    try {
        const content = await fs.readFile(DB_PATH, 'utf8');
        return JSON.parse(content);
    } catch {
        return [];
    }
};

const writeDb = async (data) => {
    await fs.writeFile(DB_PATH, JSON.stringify(data, null, 2), 'utf8');
};

const server = http.createServer(async (req, res) => {
    res.setHeader('Content-Type', 'application/json');

    if (req.url === '/api/posts' && req.method === 'GET') {
        const posts = await readDb();
        res.writeHead(200);
        res.end(JSON.stringify(posts));
    } else if (req.url === '/api/posts' && req.method === 'POST') {
        let body = '';
        req.on('data', chunk => body += chunk);
        req.on('end', async () => {
            const post = JSON.parse(body);
            post.id = Date.now();
            const posts = await readDb();
            posts.push(post);
            await writeDb(posts);
            res.writeHead(201);
            res.end(JSON.stringify(post));
        });
    } else {
        res.writeHead(404);
        res.end(JSON.stringify({ error: 'Route Not Found' }));
    }
});

server.listen(5002, () => console.log('REST API Server running on port 5002'));
